import{_ as s,o as t,c as e,a2 as n}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"HTTP/2 机制:分帧、多路复用与 HPACK","description":"这一篇只讲 HTTP/2 自己的机制:它怎么在一条 TCP 连接上并行跑多个请求。 相邻专题: - 演进全景(为什么需要 HTTP/2)→ HTTP 协议演进 - 队头阻塞的由来与浏览器端的绕行手段 → HTTP/1.1 队头阻塞与绕行","frontmatter":{},"headers":[],"relativePath":"网络/4-http2.md","filePath":"网络/4-http2.md","lastUpdated":1793930980000}'),l={name:"网络/4-http2.md"};function o(i,a,r,p,d,h){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="http-2-机制-分帧、多路复用与-hpack" tabindex="-1">HTTP/2 机制:分帧、多路复用与 HPACK <a class="header-anchor" href="#http-2-机制-分帧、多路复用与-hpack" aria-label="Permalink to &quot;HTTP/2 机制:分帧、多路复用与 HPACK&quot;">​</a></h1><blockquote><p><strong>这一篇只讲 HTTP/2 自己的机制</strong>:它怎么在一条 TCP 连接上并行跑多个请求。</p><p>相邻专题:</p><ul><li>演进全景(为什么需要 HTTP/2)→ <a href="./2-http-evolution">HTTP 协议演进</a></li><li>队头阻塞的由来与浏览器端的绕行手段 → <a href="./3-http1-problems">HTTP/1.1 队头阻塞与绕行手段</a></li><li>HTTP/3 与 QUIC → <a href="./13-http3">HTTP/3 与 QUIC 深度</a></li></ul></blockquote><h2 id="一、http-2-到底改了什么" tabindex="-1">一、HTTP/2 到底改了什么 <a class="header-anchor" href="#一、http-2-到底改了什么" aria-label="Permalink to &quot;一、HTTP/2 到底改了什么&quot;">​</a></h2><p>一句话:<strong>方法、状态码、头字段的语义完全不变,变的只是传输格式</strong>。</p><p>HTTP/2 传的还是「文本语义」的内容(JSON、HTML、图片都行),和 HTTP/1.1 一样。改动集中在传输层:</p><table tabindex="0"><thead><tr><th>改进</th><th>解决的问题</th></tr></thead><tbody><tr><td><strong>二进制分帧</strong></td><td>文本协议解析慢、无法表达「哪个片段属于哪个请求」</td></tr><tr><td><strong>多路复用</strong></td><td>一条连接上并行跑几十上百个流,不需要浏览器多开连接</td></tr><tr><td><strong>头部压缩(HPACK)</strong></td><td>每次请求都带完整头,重复头浪费带宽</td></tr><tr><td><strong>流优先级 / 服务器推送</strong></td><td>让关键资源优先传输(推送已被弃用)</td></tr></tbody></table><blockquote><p>HTTP/1.1 时代的绕行手段(6 连接、域名分片、雪碧图、内联)为什么会被废弃,见 <a href="./3-http1-problems">3-http1-problems</a>。</p></blockquote><h2 id="二、二进制分帧-binary-framing" tabindex="-1">二、二进制分帧(Binary Framing) <a class="header-anchor" href="#二、二进制分帧-binary-framing" aria-label="Permalink to &quot;二、二进制分帧(Binary Framing)&quot;">​</a></h2><h3 id="_2-1-帧结构" tabindex="-1">2.1 帧结构 <a class="header-anchor" href="#_2-1-帧结构" aria-label="Permalink to &quot;2.1 帧结构&quot;">​</a></h3><p>HTTP/1.1 是文本报文,靠 <code>\\r\\n</code> 分隔;HTTP/2 把每个请求/响应拆成<strong>帧(frame)</strong>,每帧有固定的 9 字节头:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------------------------------+</span></span>
<span class="line"><span>| Length(24) | Type(8) | Flags(8) | Stream ID(32) |</span></span>
<span class="line"><span>+-----------------------------------------------+</span></span>
<span class="line"><span>| Payload (可变长度)                            |</span></span>
<span class="line"><span>+-----------------------------------------------+</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>含义</th></tr></thead><tbody><tr><td>Length</td><td>24 bit</td><td>payload 长度(最大 16MB)</td></tr><tr><td>Type</td><td>8 bit</td><td>帧类型(DATA / HEADERS / SETTINGS / RST_STREAM / WINDOW_UPDATE ...)</td></tr><tr><td>Flags</td><td>8 bit</td><td>依赖类型的标志位(如 END_STREAM、END_HEADERS、ACK)</td></tr><tr><td>Stream ID</td><td>32 bit</td><td><strong>流标识</strong>,最高位保留,值为奇数(客户端发起的流)</td></tr></tbody></table><h3 id="_2-2-为什么要二进制" tabindex="-1">2.2 为什么要二进制 <a class="header-anchor" href="#_2-2-为什么要二进制" aria-label="Permalink to &quot;2.2 为什么要二进制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1:</span></span>
<span class="line"><span>  ┌────────────┐</span></span>
<span class="line"><span>  │ Request 1  │  ← 文本格式，靠 \\r\\n 切分</span></span>
<span class="line"><span>  └────────────┘</span></span>
<span class="line"><span>  ┌────────────┐</span></span>
<span class="line"><span>  │ Request 2  │</span></span>
<span class="line"><span>  └────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HTTP/2:</span></span>
<span class="line"><span>  ┌─────┐ ┌─────┐ ┌─────┐</span></span>
<span class="line"><span>  │帧1-1│ │帧1-2│ │帧2-1│  ← 二进制帧，可交错</span></span>
<span class="line"><span>  └─────┘ └─────┘ └─────┘</span></span>
<span class="line"><span>  同一个 TCP 连接，并行传输</span></span></code></pre></div><p>三个好处:</p><ol><li><strong>解析快</strong>:固定长度头部,不需要扫描分隔符</li><li><strong>能表达归属</strong>:<code>Stream ID</code> 让接收方知道这一帧属于哪个请求——<strong>这是乱序传输的前提</strong></li><li><strong>能承载控制信息</strong>:<code>SETTINGS</code>、<code>WINDOW_UPDATE</code>、<code>RST_STREAM</code> 这些帧在 HTTP/1.1 里根本没有对应物</li></ol><h3 id="_2-3-常见帧类型" tabindex="-1">2.3 常见帧类型 <a class="header-anchor" href="#_2-3-常见帧类型" aria-label="Permalink to &quot;2.3 常见帧类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>帧类型</th><th>作用</th></tr></thead><tbody><tr><td><code>DATA</code></td><td>传输请求/响应体</td></tr><tr><td><code>HEADERS</code></td><td>传输请求/响应头(HPACK 压缩后)</td></tr><tr><td><code>SETTINGS</code></td><td>双方协商连接参数(初始窗口大小、最大帧大小等)</td></tr><tr><td><code>WINDOW_UPDATE</code></td><td>流控:告知对方「我还能接收多少字节」</td></tr><tr><td><code>RST_STREAM</code></td><td>立即终止某个流</td></tr><tr><td><code>PING</code></td><td>保活与 RTT 探测</td></tr><tr><td><code>PRIORITY</code></td><td>设置流优先级(已废弃,见第五节)</td></tr></tbody></table><h2 id="三、多路复用-multiplexing" tabindex="-1">三、多路复用(Multiplexing) <a class="header-anchor" href="#三、多路复用-multiplexing" aria-label="Permalink to &quot;三、多路复用(Multiplexing)&quot;">​</a></h2><h3 id="_3-1-流与流-id" tabindex="-1">3.1 流与流 ID <a class="header-anchor" href="#_3-1-流与流-id" aria-label="Permalink to &quot;3.1 流与流 ID&quot;">​</a></h3><ul><li>一个 HTTP/2 连接上有多个<strong>流(stream)</strong>,每个流承载一个独立的请求/响应</li><li>每个流有唯一 ID,<strong>客户端发起的流用奇数 ID</strong>(1、3、5、7...),服务端发起的用偶数</li><li>单个连接上可同时存在<strong>几十到上百个活跃流</strong>(HTTP/1.1 同一域名只有 6 条连接)</li></ul><h3 id="_3-2-乱序发送、按-id-重组" tabindex="-1">3.2 乱序发送、按 ID 重组 <a class="header-anchor" href="#_3-2-乱序发送、按-id-重组" aria-label="Permalink to &quot;3.2 乱序发送、按 ID 重组&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                                服务端</span></span>
<span class="line"><span>   |  Stream 1 帧 (请求 A)          |</span></span>
<span class="line"><span>   |  ───────────────────────────→ |</span></span>
<span class="line"><span>   |  Stream 3 帧 (请求 B)          |</span></span>
<span class="line"><span>   |  ───────────────────────────→ |</span></span>
<span class="line"><span>   |                                |  处理 A(慢) + 处理 B(快)</span></span>
<span class="line"><span>   |  Stream 3 帧 (响应 B)         |</span></span>
<span class="line"><span>   |  ←─────────────────────────── |</span></span>
<span class="line"><span>   |  Stream 1 帧 (响应 A)         |</span></span>
<span class="line"><span>   |  ←─────────────────────────── |</span></span></code></pre></div><p><strong>关键</strong>:不再有「队」的概念。响应 B 可以先于响应 A 到达,由 <code>Stream ID</code> 把它交给正确的上层。</p><h3 id="_3-3-流的生命周期" tabindex="-1">3.3 流的生命周期 <a class="header-anchor" href="#_3-3-流的生命周期" aria-label="Permalink to &quot;3.3 流的生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>idle ──(HEADERS)──→ open ──(END_STREAM)──→ half-closed(remote) ──→ closed</span></span></code></pre></div><ul><li><code>idle</code>:流被创建但还没用</li><li><code>open</code>:双向都可以传</li><li><code>half-closed(local)</code>:本端发完了,还能收</li><li><code>half-closed(remote)</code>:对端发完了</li><li><code>closed</code>:双向都结束</li></ul><p>一个请求用完的流 ID <strong>不能复用</strong>,这是 HTTP/2 与 HTTP/1.1 keep-alive 复用连接的根本差异。</p><h3 id="_3-4-流量控制" tabindex="-1">3.4 流量控制 <a class="header-anchor" href="#_3-4-流量控制" aria-label="Permalink to &quot;3.4 流量控制&quot;">​</a></h3><p>HTTP/2 有<strong>两级窗口</strong>:</p><ul><li><strong>连接级窗口</strong>:整个连接还能收多少字节</li><li><strong>流级窗口</strong>:某一条流还能收多少字节</li></ul><p>接收方通过 <code>WINDOW_UPDATE</code> 帧给发送方「发粮」;发送方发出的字节数超过窗口就必须停下等。</p><p>这解决了一个 HTTP/1.1 没有的问题:HTTP/1.1 里,一个慢速下载的大文件会<strong>占满整条 TCP 连接</strong>,把同连接上的其他请求一起拖死。HTTP/2 的流级窗口让每条流各管各的。</p><h2 id="四、头部压缩-hpack" tabindex="-1">四、头部压缩(HPACK) <a class="header-anchor" href="#四、头部压缩-hpack" aria-label="Permalink to &quot;四、头部压缩(HPACK)&quot;">​</a></h2><p>HTTP/1.x 每次请求都带完整头(几百字节到几 KB),而实际请求之间<strong>大量头是重复的</strong>。</p><p>HPACK 的做法是<strong>表 + 索引</strong>:</p><h3 id="_4-1-静态表与动态表" tabindex="-1">4.1 静态表与动态表 <a class="header-anchor" href="#_4-1-静态表与动态表" aria-label="Permalink to &quot;4.1 静态表与动态表&quot;">​</a></h3><ul><li><strong>静态表</strong>:61 个常用头字段(name + value)预先约定好,直接用索引</li><li><strong>动态表</strong>:连接期间<strong>双方各自维护</strong>一张表,新出现的头按「先进先出」追加,超过上限就淘汰最老的</li></ul><h3 id="_4-2-编码方式" tabindex="-1">4.2 编码方式 <a class="header-anchor" href="#_4-2-编码方式" aria-label="Permalink to &quot;4.2 编码方式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1:每次都带完整 header</span></span>
<span class="line"><span>GET /api/users HTTP/1.1</span></span>
<span class="line"><span>Host: api.example.com</span></span>
<span class="line"><span>User-Agent: Mozilla/5.0 ...</span></span>
<span class="line"><span>Accept: */*</span></span>
<span class="line"><span>Cookie: session=abc123 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HTTP/2:重复头只发索引</span></span>
<span class="line"><span>:authority  → 索引 1</span></span>
<span class="line"><span>:method GET → 索引 2</span></span>
<span class="line"><span>:path /api/users → 索引 4</span></span>
<span class="line"><span>user-agent → 动态表索引 58</span></span></code></pre></div><p>两种编码:</p><ul><li><strong>索引编码</strong>:表里有的,发一个索引号(1~2 字节)</li><li><strong>字面量编码</strong>:表里没有的,发「名字 + 值」(值可以选用 <strong>Huffman 编码</strong>再压缩)</li></ul><h3 id="_4-3-效果与注意" tabindex="-1">4.3 效果与注意 <a class="header-anchor" href="#_4-3-效果与注意" aria-label="Permalink to &quot;4.3 效果与注意&quot;">​</a></h3><ul><li>头部体积通常能减少 <strong>80%~90%</strong></li><li><strong>敏感头不进动态表</strong>:因为动态表在连接内共享且带索引,明文下极易被攻击者推断内容(这也是 HTTP/2 强制 TLS 的原因之一)</li><li>动态表大小<strong>每个连接独立</strong>,所以连接复用率越高,压缩效果越好</li></ul><h2 id="五、流优先级与服务器推送" tabindex="-1">五、流优先级与服务器推送 <a class="header-anchor" href="#五、流优先级与服务器推送" aria-label="Permalink to &quot;五、流优先级与服务器推送&quot;">​</a></h2><h3 id="_5-1-优先级" tabindex="-1">5.1 优先级 <a class="header-anchor" href="#_5-1-优先级" aria-label="Permalink to &quot;5.1 优先级&quot;">​</a></h3><p>可以给不同流设置不同的传输权重,让关键资源(如 LCP 图片)优先发送。</p><blockquote><p>现状:HTTP/2 的优先级机制(<code>PRIORITY</code> 帧)<strong>已被废弃</strong>,因为实际效果不理想且实现复杂。现在判断优先级主要靠浏览器的资源加载启发式 + <code>rel=preload</code> 显式声明。</p></blockquote><h3 id="_5-2-server-push-为什么被废弃" tabindex="-1">5.2 Server Push 为什么被废弃 <a class="header-anchor" href="#_5-2-server-push-为什么被废弃" aria-label="Permalink to &quot;5.2 Server Push 为什么被废弃&quot;">​</a></h3><p>Server Push 让服务端在响应某个资源时<strong>主动推送</strong>关联资源(如 JS/CSS),省掉客户端再发请求。</p><p><strong>废弃原因</strong>:</p><ol><li><strong>预测不准</strong>:服务端猜错了要推什么,反而浪费带宽</li><li><strong>优先级冲突</strong>:浏览器自己判断资源优先级更准(比如首屏 LCP 图片)</li><li><strong>实现复杂</strong>:要维护推送队列、要处理重复推送</li></ol><p><strong>替代方案</strong>:用 <code>&lt;link rel=&quot;preload&quot;&gt;</code> / <code>rel=&quot;prefetch&quot;&gt;</code> / <code>rel=&quot;modulepreload&quot;&gt;</code> <strong>显式声明意图</strong>,浏览器在正确时机加载。这才是现在推荐的做法。</p><h2 id="六、为什么-http-2-强制要求-tls" tabindex="-1">六、为什么 HTTP/2 强制要求 TLS <a class="header-anchor" href="#六、为什么-http-2-强制要求-tls" aria-label="Permalink to &quot;六、为什么 HTTP/2 强制要求 TLS&quot;">​</a></h2><p>HTTP/1.1 可以跑在明文 TCP 上(所以有 <code>http://</code>),HTTP/2 <strong>强制要求 TLS</strong>(即 <code>h2</code>,明文的 <code>h2c</code> 几乎没人用)。</p><p>原因都是<strong>安全</strong>:</p><ul><li><strong>多路复用放大风险</strong>:所有请求走一条连接,任何中间人篡改一条流就能影响整条连接</li><li><strong>HPACK 动态表泄露</strong>:动态表在连接内共享,明文下极易被推断出访问了哪些站点与携带了什么信息</li><li><strong>请求走私(CL/TE 混淆)</strong>:伪头设计需要严格的长度校验来防止走私攻击</li></ul><blockquote><p><strong>协商方式</strong>:HTTP/2 不是运行时 Upgrade 出来的,而是通过 <strong>TLS ALPN</strong> 协商——ClientHello 里带 <code>ALPN: h2, http/1.1</code>,服务端在 ServerHello 里回 <code>ALPN: h2</code>。 细节见 <a href="./23-content-encoding-alpn">内容压缩与 ALPN</a>。</p></blockquote><h2 id="七、实战-http-2-配置" tabindex="-1">七、实战:HTTP/2 配置 <a class="header-anchor" href="#七、实战-http-2-配置" aria-label="Permalink to &quot;七、实战:HTTP/2 配置&quot;">​</a></h2><h3 id="_7-1-nginx" tabindex="-1">7.1 Nginx <a class="header-anchor" href="#_7-1-nginx" aria-label="Permalink to &quot;7.1 Nginx&quot;">​</a></h3><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl http2;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    /path/to/cert.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/cert.key;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_protocols </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_ciphers </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_prefer_server_ciphers </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>新版 Nginx(1.25.1+)推荐写成 <code>listen 443 ssl;</code> + <code>http2 on;</code>,老写法 <code>listen 443 ssl http2;</code> 仍可用但会有 deprecation 警告。</p></blockquote><h3 id="_7-2-应用层" tabindex="-1">7.2 应用层 <a class="header-anchor" href="#_7-2-应用层" aria-label="Permalink to &quot;7.2 应用层&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Next.js / Node 服务通常自动支持 HTTP/2:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 前面挂 Nginx / 云负载均衡启用 http2 即可,应用无需改动</span></span></code></pre></div><h3 id="_7-3-怎么确认真的用上了-http-2" tabindex="-1">7.3 怎么确认真的用上了 HTTP/2 <a class="header-anchor" href="#_7-3-怎么确认真的用上了-http-2" aria-label="Permalink to &quot;7.3 怎么确认真的用上了 HTTP/2&quot;">​</a></h3><p><strong>浏览器 DevTools → Network → 右键表头 → Protocol 列</strong>:</p><ul><li>显示 <code>h2</code> → HTTP/2</li><li>显示 <code>http/1.1</code> → 还在用 HTTP/1.1</li></ul><p><strong>命令行</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span></span></code></pre></div><p><strong>Chrome 内部页</strong> <code>chrome://net-internals/#http2</code> 能看到所有 HTTP/2 会话的详情。</p><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><h3 id="q1-http-2-到底改了哪四件事" tabindex="-1">Q1:HTTP/2 到底改了哪四件事? <a class="header-anchor" href="#q1-http-2-到底改了哪四件事" aria-label="Permalink to &quot;Q1:HTTP/2 到底改了哪四件事?&quot;">​</a></h3><ol><li><strong>二进制分帧</strong>:每帧 9 字节头(length 3 + type 1 + flags 1 + streamId 4),取代 HTTP/1.1 的 <code>\\r\\n</code> 文本分隔</li><li><strong>多路复用</strong>:一个连接上多个 stream 并行,<strong>HTTP 层没有队头阻塞</strong></li><li><strong>头部压缩(HPACK)</strong>:静态表(61 项)+ 动态表,重复头只发索引,通常能压掉 80~90%</li><li><strong>流优先级 / 服务器推送</strong>:优先级机制已废弃,推送已被 Chrome 弃用,改用 <code>rel=preload</code></li></ol><p><strong>注意</strong>:HTTP/2 传的还是「文本语义」的内容(JSON、HTML、图片都行),和 HTTP/1.1 完全一样,变的只是<strong>传输格式</strong>。</p><h3 id="q2-http-2-的队头阻塞解决了吗" tabindex="-1">Q2:HTTP/2 的队头阻塞解决了吗? <a class="header-anchor" href="#q2-http-2-的队头阻塞解决了吗" aria-label="Permalink to &quot;Q2:HTTP/2 的队头阻塞解决了吗?&quot;">​</a></h3><p><strong>只解决了一半,而且是最关键的那一半。</strong></p><ul><li><strong>HTTP 层</strong>:解决了。多路复用让一个慢请求不再阻塞其他 stream</li><li><strong>TCP 层</strong>:<strong>没解决</strong>。TCP 是字节流,分段传输,丢一个 TCP 段后面所有字节都得等它重传,所有 stream 一起卡住——哪怕它们的数据本身完好</li></ul><p>这就是 HTTP/3 换 QUIC(基于 UDP)的动机:让每条 stream <strong>独立重传</strong>。</p><blockquote><p>应用层与传输层队头阻塞的完整辨析见 <a href="./3-http1-problems">3-http1-problems</a> 的 2.3 节。</p></blockquote><p><strong>加分表述</strong>:「HTTP/2 解决了应用层的队头阻塞,HTTP/3 解决了传输层的队头阻塞。」</p><h3 id="q3-为什么-http-2-需要-tls-http-1-1-需要吗" tabindex="-1">Q3:为什么 HTTP/2 需要 TLS?HTTP/1.1 需要吗? <a class="header-anchor" href="#q3-为什么-http-2-需要-tls-http-1-1-需要吗" aria-label="Permalink to &quot;Q3:为什么 HTTP/2 需要 TLS?HTTP/1.1 需要吗?&quot;">​</a></h3><p>HTTP/1.1 可以跑明文 TCP(所以有 <code>http://</code>),也可以跑 TLS。</p><p>HTTP/2 <strong>强制要求 TLS</strong>,原因是<strong>安全</strong>而非性能:</p><ul><li>多路复用让所有请求走一条连接,任何中间人篡改一条流就能影响整条连接</li><li>HPACK 动态表在连接内共享,明文下极易被攻击者推断内容</li><li>伪头设计需要防止请求走私(CL/TE 混淆)</li></ul><p>浏览器只支持 <code>https://</code> 的 h2,明文 h2c 几乎没人用。协商靠 TLS <strong>ALPN</strong>,不是运行时 Upgrade。</p><h3 id="q4-server-push-是什么-为什么被废弃了" tabindex="-1">Q4:Server Push 是什么?为什么被废弃了? <a class="header-anchor" href="#q4-server-push-是什么-为什么被废弃了" aria-label="Permalink to &quot;Q4:Server Push 是什么?为什么被废弃了?&quot;">​</a></h3><p>服务端在响应某个资源时,主动把关联资源(如 JS/CSS)一并推给客户端,省掉客户端再发请求。</p><p><strong>废弃原因</strong>:</p><ol><li><strong>预测不准</strong>:服务端猜错了要推什么,反而浪费带宽</li><li><strong>优先级冲突</strong>:浏览器自己判断资源优先级更准(比如首屏 LCP 图片)</li><li><strong>实现复杂</strong>:要维护推送队列、要处理重复推送</li></ol><p><strong>替代方案</strong>:用 <code>&lt;link rel=&quot;preload&quot;&gt;</code> / <code>rel=&quot;prefetch&quot;&gt;</code> / <code>rel=&quot;modulepreload&quot;&gt;</code> 显式声明意图。</p><h3 id="q5-http-2-的流-id-是怎么用的" tabindex="-1">Q5:HTTP/2 的流 ID 是怎么用的? <a class="header-anchor" href="#q5-http-2-的流-id-是怎么用的" aria-label="Permalink to &quot;Q5:HTTP/2 的流 ID 是怎么用的?&quot;">​</a></h3><p>每个流有唯一 ID,<strong>客户端发起的流用奇数 ID</strong>,服务端发起的用偶数。帧头里带 Stream ID,接收方据此把乱序到达的帧<strong>重组回各自的流</strong>——这正是多路复用能实现的前提。一个连接上最多 2^31 条流,但同时活跃的一般只有几十条。</p><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>HTTP/2 换了<strong>传输格式</strong>没换语义:二进制分帧(9 字节头 + Stream ID)、多路复用(乱序发送按 ID 重组)、HPACK(静态表 + 动态表,省 80~90% 头部)、流优先级。</li><li>帧是 HTTP/2 的基础抽象:<code>DATA / HEADERS / SETTINGS / WINDOW_UPDATE / RST_STREAM</code> 各自承载不同职责,HTTP/1.1 里没有对应物。</li><li>多路复用带来两个新东西:<strong>流状态机</strong>(流 ID 不可复用)与<strong>两级流控</strong>(连接级 + 流级窗口),后者解决了「一个大文件拖死整条连接」。</li><li>队头阻塞只解决了一半:HTTP 层解决了,TCP 层的要靠 HTTP/3 的 QUIC。</li><li>HTTP/2 强制 TLS(多路复用放大风险 + HPACK 动态表泄露 + 防请求走私),通过 <strong>ALPN</strong> 协商而非 Upgrade;Server Push 已被废弃,改用 <code>rel=preload/prefetch</code>。</li><li>上线后先确认真的用上了:DevTools 的 Protocol 列应显示 <code>h2</code>。</li></ul><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://http2-explained.readthedocs.io/" target="_blank" rel="noreferrer">HTTP/2 详解</a> —— Daniel Stenberg</li><li><a href="https://datatracker.ietf.org/doc/html/rfc7540" target="_blank" rel="noreferrer">RFC 7540 (HTTP/2)</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7541" target="_blank" rel="noreferrer">RFC 7541 (HPACK)</a></li><li><a href="https://web.dev/http2/" target="_blank" rel="noreferrer">web.dev HTTP/2</a></li></ul>`,96)])])}const T=s(l,[["render",o]]);export{g as __pageData,T as default};
